"""The owner's bearer token — the credential the owner-only routes are gated on.

The third review's Critical is that the gate was a process-level boolean. `build_live(...,
owner_session=True)` made every request reaching the port the owner's, so an untrusted network
caller could read the decision log and run the approve route. Nothing about a boolean is a
credential: it is a thing the code says about itself, at startup, once, to nobody.

A credential has to be three things this is:

  * **Unpredictable.** `secrets.token_urlsafe(32)` — 256 bits, generated by the process, never
    derived from anything about the machine or the owner.
  * **A secret in one place.** Written to `~/.privatemesh/owner.token` at mode 0600 (the directory
    0700), or to `PM_OWNER_TOKEN_FILE` when that is set. Reading it is the whole authorization to
    act as the owner; the file is the credential, which is why it is never logged, never echoed
    into a session payload, and never put in a build.
  * **Compared in constant time.** `hmac.compare_digest` over encoded bytes. `==` on a secret
    leaks its prefix through timing, and a token whose search space is one character per guess is
    not a secret. `compare_digest` also refuses non-ASCII `str`, and a header is attacker-controlled
    text — so the encode to bytes happens here, where the failure is a refusal rather than a 500.

The token is STABLE across restarts: a second `issue()` reads the file it already wrote. A restart
that minted a new token would lock out the browser holding the old one, and the natural fix for
that is a flag that turns the gate off — which is where this started.

Sample mode does not use any of this. Its owner is the person running the demo, on their own
machine, against synthetic data, and it has no providers to reach.
"""
from __future__ import annotations

import hmac
import os
import secrets
from pathlib import Path

#: Where the token lives. The override exists for tests and for an operator who keeps their
#: secrets somewhere else; nothing in the suite may write the real path.
ENV = "PM_OWNER_TOKEN_FILE"
DEFAULT_PATH = "~/.privatemesh/owner.token"

#: Long enough that guessing is not a strategy: `token_urlsafe(32)` is 43 characters of base64.
TOKEN_BYTES = 32


def path() -> Path:
    """The token file's location. Read at CALL time, not at import: a test that sets the override
    after this module is imported still gets its own file."""
    override = os.environ.get(ENV)
    return Path(override).expanduser() if override else Path(DEFAULT_PATH).expanduser()


def issue(where: Path | None = None) -> str:
    """The owner's token, minting one only if there is not one already.

    Idempotent by design: everything that starts a live process calls this, and every one of them
    after the first must get the same token back. A token file that exists but is EMPTY — a crash
    between create and write — is replaced rather than adopted, because adopting it would make the
    empty string a valid credential.
    """
    target = Path(where) if where is not None else path()
    existing = _read(target)
    if existing is not None:
        _tighten(target)
        return existing

    token = secrets.token_urlsafe(TOKEN_BYTES)
    target.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    # `O_CREAT|O_EXCL` so two processes starting at once cannot both believe they minted it: the
    # loser gets FileExistsError and reads the winner's token instead of overwriting it.
    try:
        fd = os.open(target, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    except FileExistsError:
        adopted = _read(target)
        if adopted is not None:
            _tighten(target)
            return adopted
        # The file is there but holds nothing usable — a crash between create and write, or a
        # copy that lost its contents. Adopting it would make the empty string a valid credential,
        # so it is replaced. The exclusive create above is what keeps the racing case safe; this
        # path is only ever reached by a file that was already unusable.
        fd = os.open(target, os.O_CREAT | os.O_TRUNC | os.O_WRONLY, 0o600)
    with os.fdopen(fd, "w") as handle:
        handle.write(token + "\n")
    return token


def _read(target: Path) -> str | None:
    """The token in a file, or None when there is nothing usable there.

    A file this process cannot read is None rather than an exception: the caller is starting up,
    and "mint one" is a better answer than a traceback. `UnicodeDecodeError` is caught with `OSError`
    because a binary file is not a token either.
    """
    try:
        token = target.read_text(encoding="utf-8").strip()
    except (OSError, UnicodeDecodeError):
        return None
    return token or None


def _tighten(target: Path) -> None:
    """Bring an existing token file back to 0600.

    A file restored from a backup, or copied by an operator, can be world-readable — and the file
    is the credential. Opening it is the one moment this process is guaranteed to be looking at it.
    """
    try:
        if target.stat().st_mode & 0o077:
            os.chmod(target, 0o600)
    except OSError:
        pass


def matches(presented: str | None, expected: str | None) -> bool:
    """Is this the owner's token?

    False for every degenerate input — no header, an empty one, a non-string, a token with no
    expected value to compare against. Encoding to bytes here is what keeps a non-ASCII header from
    reaching `compare_digest`, which raises `TypeError` on one.
    """
    if not presented or not expected:
        return False
    try:
        return hmac.compare_digest(presented.encode("utf-8"), expected.encode("utf-8"))
    except (AttributeError, UnicodeError):
        return False


def bearer(header: str | None) -> str | None:
    """The token out of an `Authorization` header, or None.

    Exact by intent: `Bearer <token>`, one space, nothing either side. A parser that tolerates a
    doubled space or a lower-case scheme is a parser with two spellings of the credential, and the
    second spelling is the one nobody tests.
    """
    if not isinstance(header, str) or not header.startswith("Bearer "):
        return None
    token = header[len("Bearer "):]
    # A token with whitespace in it is not a token: it is a second spelling of the credential,
    # and the second spelling is the one nobody tests. `Bearer  x` is refused rather than trimmed.
    return None if not token or token != token.strip() else token
